export function isSZGH880MCModel(modelNumber?: string, id?: string, title?: string): boolean {
  const combined = `${modelNumber || ""} ${id || ""} ${title || ""}`.toUpperCase();
  return combined.includes("880MC") || combined.includes("880M");
}
